// Plan.h - the 2D floor plan, loaded from assets/plan.json. Owner: Erykah.
//
// Used to draw the floor plan and the minimap.
// plan.json is generated by tools/generate-floor-plan.py. Do not edit it by hand.

#pragma once
#include <array>
#include <string>
#include <vector>

namespace lumen {

// Plan space is 2D metres, +y north.
struct Vec2 {
    float x = 0.0f, y = 0.0f;
};

struct Segment {
    Vec2 a, b;
    float length() const;
    bool  horizontal() const;
};

struct Rect {
    float x0 = 0.0f, y0 = 0.0f, x1 = 0.0f, y1 = 0.0f;
    bool  contains(Vec2 p) const;
    bool  contains(Vec2 p, float margin) const;
    Vec2  centre() const;
    float width()  const { return x1 - x0; }
    float height() const { return y1 - y0; }
};

enum class Side { North, South, East, West };

struct Door {
    Side  side = Side::North;
    float a = 0.0f, b = 0.0f;   // span along the wall, in plan metres
    Segment segment(const Rect& r) const;
    Vec2    centre(const Rect& r) const;
};

// A place on a wall where a painting can hang.
struct HangPoint {
    Segment span;          // the wall run the work sits on
    Vec2    inwardNormal;  // unit vector pointing into the room
    float   width() const { return span.length(); }
};

struct RoomPlan {
    std::string id;        // "R1" .. "R5"
    std::string name;      // "Gallery One"
    std::string owner;     // the member responsible
    Rect        rect;
    Door        door;
    std::vector<Segment>   vaults;  // the line along the top of each vault
    std::vector<HangPoint> hangs;
};

struct Plan {
    float wallThickness = 0.45f;
    float wallHeight    = 4.2f;
    float vaultApex     = 6.0f;

    Rect  bounds;
    Rect  atriumRect;
    Rect  vestibuleRect;
    Rect  corridorOuter;
    Rect  corridorInner;
    Vec2  oculusCentre;
    float oculusRadius = 0.0f;

    std::vector<Rect>     niches;
    std::vector<RoomPlan> rooms;
    std::vector<Segment>  walls;   // doorways already subtracted
    std::vector<Segment>  doorways;   // every door opening
    std::vector<Vec2>     route;   // tour waypoints along the corridor

    // Where the visitor starts, facing the atrium.
    Vec2  spawn() const;
    float spawnHeadingDeg() const;

    // The room containing p, or nullptr if outside every room.
    // margin shrinks the test so the light does not flicker in the doorway.
    const RoomPlan* roomAt(Vec2 p, float margin = 0.0f) const;

    // Throws with a clear message if the file is missing or broken.
    static Plan load(const std::string& path);
};

} // namespace lumen
